using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using System.Web.Script.Serialization;
namespace DoomSNESed {
    public sealed class ConverterSetup {public List<TextReplacement> Texts=new List<TextReplacement>();public int Version=1;public string Rom,Wad;public string[] Maps;public bool Substitutions,AllowExpanded;public ConversionOptions Options;public List<GraphicReplacement> Graphics;public AudioProject Audio;}
    public sealed partial class ConverterForm {
        void ProtectInputFiles(string output){string full=Path.GetFullPath(output);foreach(string input in new[]{romPath.Text,wadPath.Text})if(!string.IsNullOrWhiteSpace(input))Bin.Require(!string.Equals(full,Path.GetFullPath(input),StringComparison.OrdinalIgnoreCase),"Choose another filename. The base ROM and PWAD are protected.");}
        void SaveSetup(){using(var dialog=new SaveFileDialog{Filter="DoomSNESconv setup|*.snconv",FileName="My Doom conversion.snconv"})if(dialog.ShowDialog(this)==DialogResult.OK)try{FlushText();ProtectInputFiles(dialog.FileName);Bin.Require(string.Equals(Path.GetExtension(dialog.FileName),".snconv",StringComparison.OrdinalIgnoreCase),"Choose a .snconv setup filename.");var setup=new ConverterSetup{Rom=romPath.Text,Wad=wadPath.Text,Maps=levels.CheckedItems.Cast<string>().ToArray(),Options=Options(),Substitutions=lossy.Checked,AllowExpanded=allowExpanded.Checked,Graphics=graphicChanges,Audio=audioChanges,Texts=textChanges};var json=ProjectJson.Create();Bin.Atomic(dialog.FileName,System.Text.Encoding.UTF8.GetBytes(json.Serialize(setup)));report.Text="Converter setup saved, including staged graphics, converted music and sound samples.\r\n"+dialog.FileName;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Save setup");}}
        void OpenSetup(){using(var dialog=new OpenFileDialog{Filter="DoomSNESconv setup|*.snconv"})if(dialog.ShowDialog(this)==DialogResult.OK)try{var json=ProjectJson.Create();var setup=json.Deserialize<ConverterSetup>(File.ReadAllText(dialog.FileName));Bin.Require(setup!=null&&setup.Version==1&&setup.Options!=null&&setup.Graphics!=null&&setup.Audio!=null,"Invalid converter setup.");int light=Array.IndexOf(new[]{0,8,16,32,64},setup.Options.LightingStep),count=Array.IndexOf(new[]{0,16,32,48,64,80},setup.Options.MonsterLimit);Bin.Require(light>=0&&count>=0&&setup.Audio.Music!=null&&setup.Audio.Sounds!=null,"Invalid converter settings.");foreach(var song in setup.Audio.Music)AudioBuild.ValidateMusic(song);romPath.Text=setup.Rom;wadPath.Text=setup.Wad;LoadWad();for(int i=0;i<levels.Items.Count;i++)levels.SetItemChecked(i,setup.Maps!=null&&setup.Maps.Contains((string)levels.Items[i]));var options=setup.Options;merge.Checked=options.MergeSectors;weld.Checked=options.WeldVertices;collapse.Checked=options.CollapseWalls;tags.Checked=options.CompactTags;bestFit.Checked=options.BestFit;closest.Checked=options.ClosestActions;reject.Checked=options.RejectDisconnected;decorations.Checked=options.RemoveDecorations;lighting.SelectedIndex=light;monsters.SelectedIndex=count;lossy.Checked=setup.Substitutions;allowExpanded.Checked=setup.AllowExpanded;textErrors.Clear();textDrafts.Clear();textChanges.Clear();textChanges.AddRange(setup.Texts??new List<TextReplacement>());graphicChanges.Clear();graphicChanges.AddRange(setup.Graphics);audioChanges.Music.Clear();audioChanges.Music.AddRange(setup.Audio.Music);audioChanges.Sounds.Clear();audioChanges.Sounds.AddRange(setup.Audio.Sounds);musicSources.Clear();AssetsChanged();RefreshAudioMaps();report.Text="Converter setup restored. Staged imports are stored in this file; source PNG/WAV/MIDI files are not required to build. Imported score notes and channel assignments are preserved for further editing.\r\n"+dialog.FileName;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Open setup");}}
    }
}
